\end{pmatrix}\begin{pmatrix}
x\\\\y\\\\z
\end{pmatrix}=\begin{pmatrix}
0&1&0\\\\0&0&1\\\\1&0&0
\end{pmatrix}\begin{pmatrix}
x\\\\y\\\\z
\end{pmatrix}
:=A\begin{pmatrix}
x\\\\y\\\\z
\end{pmatrix}
\end{aligned}

